 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    def edge_runs(col):
        runs = []
        r = 0
        while r < h:
            color = grid[r][col]
            if color == bg:
                r += 1
                continue
            lo = r
            while r < h and grid[r][col] == color:
                r += 1
            if r - lo >= 2:
                runs.append((color, lo, r))
        return runs

    left_runs, right_runs = edge_runs(0), edge_runs(w - 1)
    pairs = []
    for left in left_runs:
        for right in right_runs:
            if left[0] == right[0] and left[2] - left[1] == right[2] - right[1]:
                pairs.append((left, right))

    for left, right in pairs:
        bar_color = left[0]
        markers = [(r, c, grid[r][c])
                   for r in range(h) for c in range(1, w - 1)
                   if grid[r][c] != bg and grid[r][c] != bar_color]
        if not markers:
            continue
        marker_color = Counter(color for _, _, color in markers).most_common(1)[0][0]
        left_lo, left_hi = left[1], left[2]
        right_lo, right_hi = right[1], right[2]

        def cast(r, c, dc):
            while 0 <= c < w:
                value = grid[r][c]
                if value == marker_color:
                    out[r][c] = 4
                    return
                if value != bg:
                    return
                out[r][c] = marker_color
                c += dc

        for r, c, color in markers:
            if color != marker_color:
                continue
            if left_lo <= r < left_hi:
                cast(r, 1, 1)
                paired_r = right_lo + (r - left_lo)
                if paired_r < right_hi:
                    for cc in range(1, w - 1):
                        if grid[paired_r][cc] == bg:
                            out[paired_r][cc] = marker_color
            elif right_lo <= r < right_hi:
                cast(r, w - 2, -1)
                paired_r = left_lo + (r - right_lo)
                if paired_r < left_hi:
                    for cc in range(1, w - 1):
                        if grid[paired_r][cc] == bg:
                            out[paired_r][cc] = marker_color

    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin)), separators=(",", ":")))
